/**
 * Universal product name translator
 * Accepts a product name string or Product object, and returns the authentic
 * translated name in the specified language (falls back to English name).
 */
export function getTranslatedProductName(
  productOrName: string | { name: string; names?: Record<string, string> } | null | undefined,
  lang: string = 'en'
): string {
  if (!productOrName) return '';

  const rawName = typeof productOrName === 'string' ? productOrName : productOrName.name || '';
  if (!rawName) return '';

  if (lang === 'en') return rawName;

  // 1. Direct object-level names dictionary if present
  if (typeof productOrName === 'object' && productOrName.names && productOrName.names[lang]) {
    return productOrName.names[lang];
  }

  // 2. Exact match in master translations registry
  const translationMap = PRODUCT_NAME_TRANSLATIONS[rawName];
  if (translationMap && translationMap[lang]) {
    return translationMap[lang];
  }

  // 3. Case-insensitive lookup fallback
  const lower = rawName.toLowerCase().trim();
  for (const [key, map] of Object.entries(PRODUCT_NAME_TRANSLATIONS)) {
    if (key.toLowerCase().trim() === lower) {
      if (map[lang]) return map[lang];
      break;
    }
  }

  return rawName;
}

/**
 * Universal product description translator
 * Accepts a Product object, product name, or description string, and returns
 * the authentic translated description in the specified language.
 */
export function getTranslatedProductDescription(
  productOrDesc: any,
  lang: string = 'en'
): string {
  if (!productOrDesc) return '';

  const rawDesc = typeof productOrDesc === 'string' 
    ? productOrDesc 
    : productOrDesc.description || productOrDesc.desc || '';

  if (lang === 'en') return rawDesc;

  // 1. If product object provides a name or id, lookup directly in master map
  const rawName = typeof productOrDesc === 'object' ? (productOrDesc.name || '') : '';
  if (rawName && PRODUCT_DESCRIPTION_TRANSLATIONS[rawName]?.[lang]) {
    return PRODUCT_DESCRIPTION_TRANSLATIONS[rawName][lang];
  }

  // 2. Lookup by description match
  for (const [name, map] of Object.entries(PRODUCT_DESCRIPTION_TRANSLATIONS)) {
    if (map.en && (map.en === rawDesc || rawDesc.includes(map.en.substring(0, 30)))) {
      if (map[lang]) return map[lang];
    }
    if (name.toLowerCase() === rawDesc.toLowerCase()) {
      if (map[lang]) return map[lang];
    }
  }

  // 3. Fallback: Check if description was actually a product name
  if (PRODUCT_DESCRIPTION_TRANSLATIONS[rawDesc]?.[lang]) {
    return PRODUCT_DESCRIPTION_TRANSLATIONS[rawDesc][lang];
  }

  return rawDesc;
}

/**
 * Universal product category translator
 */
export function getTranslatedProductCategory(
  category: string | null | undefined,
  lang: string = 'en'
): string {
  if (!category) return '';
  if (lang === 'en') return category;

  const map = PRODUCT_CATEGORY_TRANSLATIONS[category];
  if (map && map[lang]) return map[lang];

  const lower = category.toLowerCase().trim();
  for (const [k, v] of Object.entries(PRODUCT_CATEGORY_TRANSLATIONS)) {
    if (k.toLowerCase().trim() === lower && v[lang]) {
      return v[lang];
    }
  }

  return category;
}

/**
 * Universal region translator
 */
export function getTranslatedRegion(
  region: string | null | undefined,
  lang: string = 'en'
): string {
  if (!region) return '';
  if (lang === 'en') return region;

  const map = PRODUCT_REGION_TRANSLATIONS[region];
  if (map && map[lang]) return map[lang];

  const lower = region.toLowerCase().trim();
  for (const [k, v] of Object.entries(PRODUCT_REGION_TRANSLATIONS)) {
    if (k.toLowerCase().trim() === lower && v[lang]) {
      return v[lang];
    }
  }

  return region;
}
